function acp_rows($sql){global $pdo;try{return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());return [];}}
$acp_reviews=acp_rows('SELECT client_name,event_type,rating,review_text FROM reviews WHERE is_published=1 ORDER BY id DESC LIMIT 6');
$acp_projects=acp_rows('SELECT title,category,image_path FROM portfolio_items WHERE is_published=1 ORDER BY sort_order,id DESC LIMIT 6');
$acp_galleries=acp_rows("SELECT event_name,guest_link FROM client_galleries WHERE status='active' ORDER BY id DESC LIMIT 6");
$acp_stats=['clients'=>(int)$pdo->query('SELECT COUNT(*) FROM clients')->fetchColumn(),'projects'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='completed'")->fetchColumn()];
function acp_escape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
